import React, { useMemo, useState } from "react";
import { awards, AwardCategory } from "./Awards.data";
import { Section, SectionContainer, FilterRow, FilterPill, YearRow, Timeline, TimelineItem, Dot, DateLabel, Card, Title, Org, Desc } from "./Awards.styles";

const categoryOptions: { id: AwardCategory | "all"; label: string }[] = [
  { id: "all", label: "All" },
  { id: "teaching", label: "Teaching" },
  { id: "research", label: "Research" },
  { id: "scholarship", label: "Scholarship" },
  { id: "academic", label: "Academic" },
];

const Awards: React.FC = () => {
  const [activeCategory, setActiveCategory] = useState<"all" | AwardCategory>("all");
  const [activeYear, setActiveYear] = useState<string>("all");

  const years = useMemo(() => {
    const yearSet = new Set<string>();
    awards.forEach((a) => {
      const y = a.date.split(" ").pop();
      if (y) yearSet.add(y);
    });
    return Array.from(yearSet).sort((a, b) => Number(b) - Number(a));
  }, []);

  const filtered = useMemo(() => {
    return awards.filter((a) => {
      const matchCategory = activeCategory === "all" || a.categories.includes(activeCategory);
      const year = a.date.split(" ").pop();
      const matchYear = activeYear === "all" || year === activeYear;
      return matchCategory && matchYear;
    });
  }, [activeCategory, activeYear]);

  return (
    <Section id="awards">
      <SectionContainer>
        <FilterRow>
          {categoryOptions.map((opt) => (
            <FilterPill key={opt.id} active={activeCategory === opt.id} onClick={() => setActiveCategory(opt.id as typeof activeCategory)}>
              {opt.label}
            </FilterPill>
          ))}
        </FilterRow>
        <YearRow>
          <FilterPill active={activeYear === "all"} onClick={() => setActiveYear("all")}>
            All years
          </FilterPill>
          {years.map((y) => (
            <FilterPill key={y} active={activeYear === y} onClick={() => setActiveYear(y)}>
              {y}
            </FilterPill>
          ))}
        </YearRow>

        <Timeline>
          {filtered.map((award, idx) => (
            <TimelineItem key={`${award.title}-${idx}`}>
              <Dot />
              <DateLabel>{award.date}</DateLabel>
              <Card>
                <Title>{award.title}</Title>
                <Org>{award.org}</Org>
                <Desc>{award.description}</Desc>
              </Card>
            </TimelineItem>
          ))}
        </Timeline>
      </SectionContainer>
    </Section>
  );
};

export default Awards;
